  (* [comment removed for export] *)
  Section Post.
    Variables (m' : mem) (b1 actx : Z).
    Let idv := d_putid d (depot_hash T).
    Let P := outside W.
    Hypothesis MU : munch W m m'.
    Hypothesis WM : wmono bsegs m m'.
    Hypothesis B1 : 0 <= b1 < 256 /\ b1 mod 128 = 17.
    Hypothesis HDR' : rw_cells bsegs m' (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)].
    Hypothesis UW' : rw_cells bsegs m' U [C8 (wz idv)].
    Hypothesis TST' : stk bsegs m' (TH + 2800) (TH + 3168).
    Hypothesis UNW' : rw_cells bsegs m' (TH + 3168) [C1 (b8 0)].
    Hypothesis FLG' : rw_cells bsegs m' AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)].
    Hypothesis IA' : ia_after m'.
    Hypothesis SHF' : u8arr bsegs m' (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size))).
    Hypothesis TQc' : rw_cells bsegs m' (TH + OT_TQ) [C8 (wz k); C8 (wz (hd 0 (map qb_addr l))); C8 (wz LA); C8 (wz (qc_bytes tq + size))].
    Hypothesis LB' : rw_cells bsegs m' LA [C8 (wz 0); C8 (wz (qb_size lb + size)); C8 (wz (lcount + 1))].
    Hypothesis LCHK' : u64arr bsegs m' (LA + 24) (wlist (qb_chunks lb ++ [U + -16])).
    Hypothesis LJ' : stk bsegs m' (LA + 32 + 8 * lcount) (LA + kBatchSize).

    Let AG : agree_on P m m'. Proof. apply munch_agree. exact MU. Qed.

    (* [comment removed for export] *)
    Let l0 := removelast l.
    Let LSPLIT : l = l0 ++ [lb]. Proof. unfold l0, lb. apply app_removelast_last. exact (proj1 NN). Qed.
    Let TQL : qc_list tq' = l0 ++ [lb'] /\ qc_bytes tq' = qc_bytes tq + size.
    Proof.
      split; [| reflexivity]. unfold tq', tq_app. cbn [qc_list]. fold l lb. fold LA lcount. unfold lb'.
      rewrite LSPLIT at 1 2. rewrite firstn_removelast. reflexivity.
    Qed.
    Let NNf : need_new tq = false. Proof. exact (need_new_false tq (proj1 NN) (proj2 NN)). Qed.
